@media (max-width: 640px){.rs-field{gap:0.5rem}}
.rs-field-label{font-size:0.75rem;font-weight:600;color:var(--text-secondary);letter-spacing:-0.01em;line-height:16px}
@media (max-width: 640px){.rs-field-label{font-size:var(--control-label)}}
.rs-field-hint{margin:0;font-size:0.75rem;font-weight:500;color:var(--text-secondary);letter-spacing:-0.01em;line-height:16px}
