"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";

interface TabsContextValue {
  value: string;
  setValue: (value: string) => void;
  idBase: string;
  /** Panels currently mounted, so a tab only claims aria-controls for one that exists. */
  panels: ReadonlySet<string>;
  registerPanel: (value: string) => () => void;
}

const TabsContext = React.createContext<TabsContextValue | null>(null);

function useTabsContext(component: string): TabsContextValue {
  const ctx = React.useContext(TabsContext);
  if (!ctx) throw new Error(`<${component}> must be used inside <Tabs>`);
  return ctx;
}

const styles = stylex.create({
  list: {
    display: "flex",
    alignItems: {
      default: "baseline",
      [mq.phone]: "stretch",
    },
    gap: {
      default: "1.375rem",
      [mq.phone]: 0,
    },
    width: {
      default: null,
      [mq.phone]: "100%",
    },
    maxWidth: {
      default: "22.5rem",
      [mq.phone]: "none",
    },
    borderWidth: 0,
    borderStyle: "none",
    borderBottomWidth: {
      default: 0,
      [mq.phone]: vlak.hairline,
    },
    borderBottomStyle: {
      default: "none",
      [mq.phone]: "solid",
    },
    borderBottomColor: {
      default: "transparent",
      [mq.phone]: vlak.divider,
    },
    boxShadow: "none",
    backgroundColor: "transparent",
  },
  vertical: {
    flexDirection: "column",
    alignItems: "stretch",
    gap: 0,
    borderBottomWidth: 0,
    borderBottomStyle: "none",
  },
  tab: {
    appearance: "none",
    boxSizing: "border-box",
    flexGrow: {
      default: null,
      [mq.phone]: 1,
    },
    flexShrink: {
      default: null,
      [mq.phone]: 1,
    },
    flexBasis: {
      default: null,
      [mq.phone]: 0,
    },
    display: {
      default: null,
      [mq.phone]: "inline-flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    justifyContent: {
      default: null,
      [mq.phone]: "center",
    },
    minHeight: {
      default: null,
      [mq.phone]: vlak.hit,
    },
    paddingBlock: {
      default: "0.5rem",
      [mq.phone]: 0,
    },
    paddingInline: {
      default: 0,
      [mq.phone]: "0.5rem",
    },
    fontSize: {
      default: "0.875rem",
      [mq.phone]: vlak.controlFs,
    },
    fontFamily: "inherit",
    fontWeight: 400,
    color: {
      default: vlak.gray,
      [mq.forcedColors]: "ButtonText",
    },
    letterSpacing: "-0.01em",
    textDecoration: "none",
    textAlign: {
      default: "start",
      [mq.phone]: "center",
    },
    backgroundColor: "transparent",
    backgroundImage: "none",
    boxShadow: "none",
    borderWidth: 0,
    borderStyle: "none",
    borderRadius: 0,
    cursor: "pointer",
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  active: {
    color: {
      default: vlak.ink,
      [mq.forcedColors]: "Highlight",
    },
    fontWeight: 600,
    borderWidth: 0,
    borderStyle: "none",
    /* The underline is a box-shadow on paper; forced colors drop shadows, so it becomes a border there. */
    boxShadow: "inset 0 -1px 0",
    borderBottomWidth: {
      default: 0,
      [mq.forcedColors]: 2,
    },
    borderBottomStyle: {
      default: "none",
      [mq.forcedColors]: "solid",
    },
    borderBottomColor: {
      default: "transparent",
      [mq.forcedColors]: "Highlight",
    },
  },
});

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(function Tabs(
  { value, defaultValue, onValueChange, children, ...props },
  ref,
) {
  const idBase = React.useId();
  const [panels, setPanels] = React.useState<ReadonlySet<string>>(() => new Set());
  const registerPanel = React.useCallback((v: string) => {
    setPanels((prev) => (prev.has(v) ? prev : new Set(prev).add(v)));
    return () => setPanels((prev) => {
      if (!prev.has(v)) return prev;
      const next = new Set(prev);
      next.delete(v);
      return next;
    });
  }, []);
  const [inner, setInner] = React.useState(defaultValue ?? "");
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const setValue = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
  };
  return (
    <div ref={ref} {...props}>
      <TabsContext.Provider value={{ value: current, setValue, idBase, panels, registerPanel }}>
        {children}
      </TabsContext.Provider>
    </div>
  );
});

export interface TabListProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Stacked tabs answer Up/Down instead of Left/Right. */
  orientation?: "horizontal" | "vertical";
}

/** Roving tabs: arrows step, Home/End jump, and selection follows focus. */
export const TabList = React.forwardRef<HTMLDivElement, TabListProps>(function TabList(
  { orientation = "horizontal", className, style, onKeyDown, ...props },
  ref,
) {
  const vertical = orientation === "vertical";
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    const prevKey = vertical ? "ArrowUp" : "ArrowLeft";
    const nextKey = vertical ? "ArrowDown" : "ArrowRight";
    if (e.key !== prevKey && e.key !== nextKey && e.key !== "Home" && e.key !== "End") return;
    const tabs = Array.from(
      e.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)'),
    );
    const index = tabs.indexOf(document.activeElement as HTMLButtonElement);
    if (index === -1 || tabs.length === 0) return;
    e.preventDefault();
    const next =
      e.key === "Home"
        ? 0
        : e.key === "End"
          ? tabs.length - 1
          : e.key === nextKey
            ? (index + 1) % tabs.length
            : (index - 1 + tabs.length) % tabs.length;
    tabs[next]?.focus();
    tabs[next]?.click();
  };
  const sx = rs(["rs-tabs", vertical && "rs-tabs-vertical", className], styles.list, vertical && styles.vertical);
  return (
    <div
      ref={ref}
