"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { useMergedRefs } from "./merge-refs";

import { Icon } from "./icons";

export interface DropdownMenuItem {
  label?: React.ReactNode;
  /** Plain text for type-ahead when `label` is not a string. */
  searchText?: string;
  onSelect?: () => void;
  disabled?: boolean;
  separator?: boolean;
}

export interface DropdownMenuProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  items: DropdownMenuItem[];
}

export const menuStyles = stylex.create({
  select: {
    position: "relative",
    display: {
      default: "inline-block",
      [mq.phone]: "block",
    },
    minWidth: {
      default: "11.25rem",
      [mq.phone]: 0,
    },
    width: {
      default: null,
      [mq.phone]: "100%",
    },
  },
  dropdown: {
    boxSizing: "border-box",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: "0.75rem",
    paddingBlock: {
      default: "0.5625rem",
      [mq.phone]: "0.75rem",
    },
    paddingInline: {
      default: "0.75rem",
      [mq.phone]: "0.875rem",
    },
    borderWidth: vlak.hairline,
    borderStyle: "solid",
    borderColor: vlak.divider,
    borderRadius: {
      default: vlak.radiusSm,
      [mq.phone]: 0,
    },
    fontSize: {
      default: "0.875rem",
      [mq.phone]: vlak.controlFs,
    },
    color: vlak.ink,
    letterSpacing: "-0.01em",
    cursor: "pointer",
    fontFamily: "inherit",
    backgroundColor: "transparent",
    width: "100%",
    minHeight: {
      default: null,
      [mq.phone]: vlak.hit,
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  menu: {
    boxSizing: "border-box",
    borderWidth: vlak.hairline,
    borderStyle: "solid",
    borderColor: vlak.divider,
    borderRadius: {
      default: vlak.radiusSm,
      [mq.phone]: 0,
    },
    marginTop: {
      default: "0.375rem",
      [mq.phone]: 0,
    },
    overflow: "hidden",
    backgroundColor: vlak.paper,
    boxShadow: {
      default: "0 8px 24px rgba(0,0,0,0.06)",
      [mq.phone]: "none",
    },
  },
  menuOverlay: {
    position: "absolute",
    top: "100%",
    insetInlineStart: 0,
    insetInlineEnd: 0,
    zIndex: vlak.zFloat,
  },
  menuFixed: {
    position: "fixed",
    zIndex: vlak.zFloat,
    marginTop: 0,
    minWidth: "10rem",
  },
  menuCal: {
    insetInlineEnd: "auto",
    padding: "0.75rem",
  },
  menuCombobox: {
    position: "absolute",
    top: "100%",
    insetInlineStart: 0,
    insetInlineEnd: 0,
    zIndex: vlak.zFloat,
    maxHeight: "15rem",
    overflowY: "auto",
  },
  item: {
    boxSizing: "border-box",
    display: {
      default: "block",
      [mq.phone]: "flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    paddingBlock: {
      default: "0.5625rem",
      [mq.phone]: "0.75rem",
    },
    paddingInline: {
      default: "0.75rem",
      [mq.phone]: "0.875rem",
    },
    fontSize: {
      default: "0.875rem",
      [mq.phone]: vlak.controlFs,
    },
    color: vlak.ink,
    letterSpacing: "-0.01em",
    borderBottomWidth: {
      default: vlak.hairline,
      ":last-child": 0,
    },
    borderBottomStyle: "solid",
    borderBottomColor: vlak.divider,
    borderInlineStartWidth: 0,
    borderInlineEndWidth: 0,
    borderTopWidth: 0,
    width: "100%",
    textAlign: "start",
    cursor: "pointer",
    backgroundColor: "transparent",
    fontFamily: "inherit",
    minHeight: {
      default: null,
      [mq.phone]: vlak.hit,
    },
    /* The menu clips at its edge, so the ring sits inside the row. */
