export interface DonutProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
  size?: number;
  label?: React.ReactNode;
  unit?: string;
  valueFormat?: (value: number) => string;
  spot?: boolean | string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
}

export const Donut = React.forwardRef<HTMLDivElement, DonutProps>(function Donut({
  value,
  max = 100,
  size = 184,
  label,
  unit,
  valueFormat,
  className,
  spot,
  locale,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: DonutProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const format = valueFormat ?? ((v: number) => `${Math.round((v / max) * 100)}%`);
  const pct = Math.max(0, Math.min(1, max === 0 ? 0 : value / max));
  const caption = typeof label === "string" ? label : undefined;
  const ids = React.useId();
  const valueId = `${ids}-value`;
  const captionId = `${ids}-caption`;
  const titleId = `${ids}-title`;
  const c = size / 2;
  const r = size * 0.375;
  const circumference = 2 * Math.PI * r;
  const shown = `${format(value)}${unit ? ` ${unit}` : ""}`;
  const svg = rs(["rs-chart-plot", "rs-chart-donut"], chartStyles.svg, chartStyles.plot, styles.donut);
  const track = rs(["rs-chart-donut-track"], styles.track);
  const valueSx = rs(["rs-chart-donut-value"], styles.value);
  const labelSx = rs(["rs-chart-donut-label"], styles.label);
  const captionSx = rs(["rs-chart-donut-caption"], styles.caption);
  const name = ariaLabelledBy
    ? { "aria-labelledby": ariaLabelledBy }
    : ariaLabel
      ? { "aria-label": ariaLabel }
      : {
          "aria-labelledby": [caption ? captionId : label ? titleId : null, valueId].filter(Boolean).join(" "),
        };
  return (
    <ChartField ref={ref} spot={spot} className={className ? `rs-chart-donut-wrap ${className}` : "rs-chart-donut-wrap"} {...props}>
      <svg
        className={svg.className}
        style={svg.style}
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        role="img"
        {...name}
      >
        <circle className={track.className} style={track.style} cx={c} cy={c} r={r} />
        <circle
          className={valueSx.className}
          style={valueSx.style}
          cx={c}
          cy={c}
          r={r}
          strokeDasharray={`${pct * circumference} ${circumference}`}
          transform={`rotate(-90 ${c} ${c})`}
        />
        <text id={valueId} className={labelSx.className} style={labelSx.style} x={c} y={caption ? c - 3 : c + 7} textAnchor="middle">
          {shown}
        </text>
        {caption && (
          <text id={captionId} className={captionSx.className} style={captionSx.style} x={c} y={c + 16} textAnchor="middle">
            {caption}
          </text>
        )}
      </svg>
      {label && !caption ? <ChartTitle id={titleId}>{label}</ChartTitle> : null}
      <SrTable
        caption={caption ?? "Donut"}
        labels={[caption ?? "Value"]}
        series={[
          { name: unit ?? "Value", values: [defaultFormat(value, undefined, locale)] },
          { name: "Of", values: [defaultFormat(max, undefined, locale)] },
          { name: "Share", values: [`${Math.round(pct * 100)}%`] },
        ]}
      />
    </ChartField>
  );
});

export type ShareSlice = { label: string; value: number };

export interface ShareProps extends React.HTMLAttributes<HTMLDivElement> {
  slices: ShareSlice[];
  unit?: string;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
}

export const Share = React.forwardRef<HTMLDivElement, ShareProps>(function Share({
  slices,
  unit,
  valueFormat,
  className,
  spot,
  locale,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: ShareProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit, locale));
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  const percent = (v: number) => `${defaultFormat((v / total) * 100, undefined, locale)}%`;
  const share = rs(["rs-chart-share"], styles.share);
  const name = ariaLabelledBy
    ? { "aria-labelledby": ariaLabelledBy }
    : {
        "aria-label": ariaLabel ?? `Share: ${slices.map((s) => `${s.label} ${percent(s.value)}`).join(", ")}`,
      };
  return (
    <ChartField ref={ref} spot={spot} className={className} {...props}>
      <div className={share.className} style={share.style} role="img" {...name}>
        {slices.map((s, i) => {
          const seg = rs(
            ["rs-chart-share-seg", i === 0 && "rs-chart-share-seg-spot"],
            styles.seg,
            i === 0 && styles.segSpot,
          );
          return (
            <div
              key={s.label}
              className={seg.className}
              style={{ ...seg.style, flex: `${s.value} 1 0` }}
              title={`${s.label} ${format(s.value)}`}
            />
          );
        })}
      </div>
      <ChartLegend aria-hidden="true">
        {slices.map((s) => (
          <ChartLegendItem key={s.label}>
            {s.label} {percent(s.value)}
          </ChartLegendItem>
        ))}
      </ChartLegend>
      <SrTable
        caption="Share"
        labels={slices.map((s) => s.label)}
        series={[
          { name: unit ?? "Value", values: slices.map((s) => format(s.value)) },
          { name: "Share", values: slices.map((s) => percent(s.value)) },
        ]}
      />
    </ChartField>
  );
});

"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak } from "../tokens.stylex";
import { rs } from "../rs";
import {
  ChartCanvas,
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  PLOT,
  SrTable,
  chartStyles,
  defaultFormat,
  describePlot,
  niceMax,
  plotName,
  plotProps,
  stepCursor,
  ticksFor,
  useChartWidth,
} from "./frame";

const styles = stylex.create({
  hist: {
    fill: vlak.divider,
    stroke: "none",
    borderRadius: 0,
  },
});

export type HistogramBin = { label: string; count: number };

export interface HistogramProps extends React.HTMLAttributes<HTMLDivElement> {
  bins: HistogramBin[];
  height?: number;
  unit?: string;
  yLabel?: string;
  grid?: boolean;
  ticks?: number;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
  /** BCP 47 tag for number formatting; undefined is the reader's own. */
  locale?: string;
}

export const Histogram = React.forwardRef<HTMLDivElement, HistogramProps>(function Histogram({
  bins,
  height = 204,
  unit,
  yLabel,
  grid = true,
  ticks = 4,
  valueFormat,
  className,
  spot,
  locale,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: HistogramProps, ref: React.ForwardedRef<HTMLDivElement>) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, undefined, locale));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit, locale));
  const [hover, setHover] = React.useState<number | null>(null);
  const [canvasRef, W] = useChartWidth<HTMLDivElement>();
  const titleId = React.useId();
  const { ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const max = niceMax(Math.max(...bins.map((b) => b.count), 1));
  const yTicks = ticksFor(max, ticks);
  const gap = 1;
  const bw = (plotW - gap * Math.max(0, bins.length - 1)) / Math.max(1, bins.length);
  const active = hover != null ? bins[hover] : null;

  const svg = rs(["rs-chart-svg"], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const hist = rs(["rs-chart-hist", Boolean(spot) && "rs-chart-bar-spot"], styles.hist, Boolean(spot) && chartStyles.barSpot);

  const name = plotName(
    { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy },
    yLabel ? titleId : undefined,
    describePlot("Histogram", [`${bins.length} bins`], unit),
  );
  const a11y = plotProps(
    name,
    (key) => {
      const next = stepCursor(key, hover, bins.length);
      if (next === undefined) return false;
      setHover(next);
      return true;
    },
    () => setHover(null),
  );

  return (
    <ChartField ref={ref} spot={spot} className={className} {...props}>
      {yLabel && (
        <ChartHead>
          <ChartTitle id={titleId}>{yLabel}</ChartTitle>
        </ChartHead>
      )}
      <ChartCanvas ref={canvasRef}>
        <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} {...a11y}>
          <g className={plot.className} style={plot.style} aria-hidden="true">
            {grid &&
              yTicks.map((t) => {
                const y = MT + plotH - (t / max) * plotH;
                return (
                  <g key={t}>
                    <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={y} y2={y} />
                    <text className={axis.className} style={axis.style} x={ML - 6} y={y + 3.5} textAnchor="end">
                      {format(t)}
                    </text>
                  </g>
                );
              })}
            <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
            {bins.map((b, i) => {
              const h = (b.count / max) * plotH;
              const x = ML + i * (bw + gap);
              const y = MT + plotH - h;
              return (
                <g key={b.label} onPointerEnter={() => setHover(i)} onPointerLeave={() => setHover(null)}>
                  <rect className={hist.className} style={hist.style} x={x} y={y} width={bw} height={h} />
                  <text className={axis.className} style={axis.style} x={x + bw / 2} y={height - 4} textAnchor="middle">
                    {b.label}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>
        {active && (
          <ChartTip
            left={ML + (hover ?? 0) * (bw + gap) + bw / 2}
            top={MT + plotH - (active.count / max) * plotH}
            label={active.label}
            rows={[{ value: tip(active.count) }]}
          />
        )}
      </ChartCanvas>
      {unit && (
        <ChartLegend aria-hidden="true">
          <ChartLegendItem>{unit}</ChartLegendItem>
        </ChartLegend>
      )}
      <SrTable
        caption={yLabel ?? "Histogram"}
        labels={bins.map((b) => b.label)}
        series={[{ name: unit ?? "Count", values: bins.map((b) => b.count) }]}
      />
    </ChartField>
  );
});

