/** One cell per character. Auto-advance, backspace, paste. */
export const InputOTP = React.forwardRef<HTMLDivElement, InputOTPProps>(function InputOTP({
  length = 6,
  onChange,
  onComplete,
  className,
  style,
  "aria-label": ariaLabel = "One-time code",
