              onPointerEnter={() => {
                if (openIndex !== null && openIndex !== index) openMenu(index);
              }}
            >
              <span>{entry.label}</span>
              <Icon name="chevron-right" rotate={90} />
            </button>
            {isOpen && (
              <MenuPanel
                id={menuId}
                items={entry.items}
                labelledBy={triggerId}
                initial={initial}
                className={menu.className}
                style={menu.style}
                onClose={closeMenu}
                onHorizontal={(dir) => moveTo(index + dir)}
              />
            )}
          </div>
        );
      })}
    </div>
  );
});

